namespace sv_f4b99110cd964484aa28d9c647c14be2.Client.Services;

public record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public record StatusUpdate(
    string Description,
    string Location,
    DateTimeOffset Timestamp);

namespace sv_f4b99110cd964484aa28d9c647c14be2.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;

namespace sv_f4b99110cd964484aa28d9c647c14be2.Client.Services;

public class HttpShipmentService : IShipmentService
{
    private readonly HttpClient _http;

    public HttpShipmentService(HttpClient http)
    {
        _http = http;
    }

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await _http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct);
    }
}

using sv_f4b99110cd964484aa28d9c647c14be2.Client.Services;

namespace sv_f4b99110cd964484aa28d9c647c14be2.Services;

public class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new ShipmentDetails(
            TrackingNumber: "PKG-001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 20, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates: new List<StatusUpdate>
            {
                new("Package picked up", "New York, NY", new DateTimeOffset(2026, 6, 14, 9, 30, 0, TimeSpan.Zero)),
                new("Departed facility", "New York, NY", new DateTimeOffset(2026, 6, 14, 14, 0, 0, TimeSpan.Zero)),
                new("Arrived at sorting center", "Chicago, IL", new DateTimeOffset(2026, 6, 15, 22, 15, 0, TimeSpan.Zero)),
                new("In transit to destination", "Chicago, IL", new DateTimeOffset(2026, 6, 16, 8, 0, 0, TimeSpan.Zero)),
            }),

        ["PKG-002"] = new ShipmentDetails(
            TrackingNumber: "PKG-002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 15, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates: new List<StatusUpdate>
            {
                new("Package picked up", "Seattle, WA", new DateTimeOffset(2026, 6, 12, 10, 0, 0, TimeSpan.Zero)),
                new("In transit", "Portland, OR", new DateTimeOffset(2026, 6, 13, 6, 45, 0, TimeSpan.Zero)),
                new("Out for delivery", "San Francisco, CA", new DateTimeOffset(2026, 6, 15, 8, 0, 0, TimeSpan.Zero)),
                new("Delivered", "San Francisco, CA", new DateTimeOffset(2026, 6, 15, 11, 32, 0, TimeSpan.Zero)),
            }),

        ["PKG-003"] = new ShipmentDetails(
            TrackingNumber: "PKG-003",
            Status: "Processing",
            Location: "Dallas, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 22, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates: new List<StatusUpdate>
            {
                new("Label created", "Dallas, TX", new DateTimeOffset(2026, 6, 16, 15, 0, 0, TimeSpan.Zero)),
                new("Package received at facility", "Dallas, TX", new DateTimeOffset(2026, 6, 16, 20, 30, 0, TimeSpan.Zero)),
            }),
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate a slow backend
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

